let mobileTables: Map<number, readonly number[]>[] | undefined;

export function mobileDetectionTable(carrier: number): ReadonlyMap<number, readonly number[]> {
  mobileTables ??= loadMobileTables();
  return mobileTables[carrier];
}

function loadMobileTables(): Map<number, readonly number[]>[] {
  const data = inflateRawSync(Buffer.from(mobileData, 'base64'));
  const tables: Map<number, readonly number[]>[] = [];
  let table = new Map<number, readonly number[]>();
  for (let offset = 0; offset < data.length; offset += 12) {
    const code = data.readUInt32BE(offset);
    if (code === 0) {
      tables.push(table);
      table = new Map();
      continue;
    }
    const first = data.readUInt32BE(offset + 4);
    const second = data.readUInt32BE(offset + 8);
    table.set(code, second === 0 ? [first] : [first, second]);
  }
  return tables;
}

